"node -e "
const fs = require('fs');
const text = fs.readFileSync('input_raw_full.txt', 'utf8');
const lines = text.split(/\r?\n/);
let headerIndex = -1;
for (let i = 0; i < lines.length; i++) {
  if (lines[i].includes('순번') && lines[i].includes('기업명')) {
    headerIndex = i;
    break;
  }
}
console.log('Header index:', headerIndex);
const header = lines[headerIndex].split('\t');
console.log('Header columns:', header);

const validRows = [];
for (let i = headerIndex + 1; i < lines.length; i++) {
  const line = lines[i];
  if (!line.trim() || line.startsWith('<') || line.startsWith('NOTE:')) continue;
  const cols = line.split('\t');
  if (/^\d+$/.test(cols[0].trim())) {
    validRows.push(cols);
  }
}

console.log('Valid data rows:', validRows.length);
console.log('Row 1:', validRows[0]);
console.log('Last row:', validRows[validRows.length - 1]);

// Analyze phone numbers
let hasPhone = 0;
let missingPhone = [];
for (const r of validRows) {
  // Column 9 is 전화번호 (0-indexed)
  const phone = (r[9] || '').trim();
  if (phone) {
    hasPhone++;
  } else {
    missingPhone.push({
      seq: r[0],
      name: r[1],
      ceo: r[2],
      bizNo: r[5],
      corpNo: r[6],
      industry: r[7],
      address: r[8]
    });
  }
}

console.log('Total rows:', validRows.length);
console.log('Rows with phone:', hasPhone);
console.log('Rows missing phone:', missingPhone.length);
fs.writeFileSync('missing_phone_targets.json', JSON.stringify(missingPhone, null, 2), 'utf8');
""

